public class PairTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Pair<String> letters = new Pair<>("a", "b");
        check("getFirst() on Pair<String>", "a", letters.getFirst());
        check("getSecond() on Pair<String>", "b", letters.getSecond());

        Pair<String> flipped = letters.swapped();
        check("swapped().getFirst()", "b", flipped == null ? null : flipped.getFirst());
        check("swapped().getSecond()", "a", flipped == null ? null : flipped.getSecond());
        check("original pair is unchanged", "a", letters.getFirst());
        check("swapped() returns a new object", false, flipped == letters);

        Pair<Integer> numbers = new Pair<>(1, 2);
        check("getFirst() on Pair<Integer>", 1, numbers.getFirst());
        Pair<Integer> flippedNumbers = numbers.swapped();
        check("swapped Pair<Integer> first", 2, flippedNumbers == null ? null : flippedNumbers.getFirst());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

